const leavesForModel = `-- name: LeavesForModel :many
SELECT id, model_id, bucket_id, kind, symbol, name, target_bps, alert_threshold_bps, sort_order FROM allocation_leaves WHERE model_id = $1 ORDER BY sort_order ASC
`

func (q *Queries) LeavesForModel(ctx context.Context, modelID uuid.UUID) ([]AllocationLeafe, error) {
	rows, err := q.db.Query(ctx, leavesForModel, modelID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AllocationLeafe{}
	for rows.Next() {
		var i AllocationLeafe
		if err := rows.Scan(
			&i.ID,
			&i.ModelID,
			&i.BucketID,
			&i.Kind,
			&i.Symbol,
			&i.Name,
			&i.TargetBps,
			&i.AlertThresholdBps,
			&i.SortOrder,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

